bool webgpu_input(gpu::Gpu*g,const float*input,Image&out,const Mat3&matrix,const double*gains,bool encoded,uint32_t mode,std::string&error){double m[9];matrix.to_row_major(m);float p[12];for(int i=0;i<9;i++)p[i]=float(m[i]);for(int i=0;i<3;i++)p[9+i]=float(gains[i]);const uint32_t meta[]={out.w*out.h,mode,encoded?1u:0u};auto source=g->upload(input,out.bytes(),error),params=g->upload(p,sizeof p,error);if(!source||!params)return false;return g->dispatch("spk_web_input",{gpu::Arg::buf(source),gpu::Arg::buf(params),gpu::Arg::inline_bytes(meta,3),gpu::Arg::buf(out.buf)},size_t(out.w)*out.h,error);}
bool webgpu_output(gpu::Gpu*g,const Image&scan,float*output,const Json&o,Colour&colour,SetupCache&cache,bool isDI,std::string&error){auto get=[&](const char*k){return o.at(k).as_double(0);};const auto dst=o.at("targetColorSpace").is_string()?o.at("targetColorSpace").as_string():"sRGB";Mat3 convert=Mat3::identity();if(dst!="ProPhoto RGB"&&!colour.matrix_RGB_to_RGB("ProPhoto RGB",dst,"CAT02",convert,error))return false;
 float p[28]={};const double gain=std::exp2(get("exposure"));p[0]=float(gain*(1+get("temperature")*.002));p[1]=float(gain*std::exp2(-get("postTint")/150));p[2]=float(gain*(1-get("temperature")*.002));p[3]=float(1+get("contrast")/100);p[4]=float(1+get("saturation")/100);
 const char*keys[]={"curveShadows","curveMid","curveHighlights","balanceR","balanceG","balanceB","shadowR","shadowG","shadowB","highlightR","highlightG","highlightB"};for(int i=0;i<12;i++){p[7+i]=float(get(keys[i]));if(p[7+i]!=0)p[6]=1;if(i<3&&p[7+i]!=0)p[5]=1;}if(p[3]!=1||p[4]!=1)p[6]=1;double mat[9];convert.to_row_major(mat);for(int i=0;i<9;i++)p[19+i]=float(mat[i]);const uint32_t meta[]={scan.w*scan.h,scan.w,scan.h,isDI?1u:0u};auto params=g->upload(p,sizeof p,error),linear=g->alloc(scan.bytes(),error);if(!params||!linear)return false;
 if(!g->dispatch("spk_web_grade",{gpu::Arg::buf(scan.buf),gpu::Arg::buf(params),gpu::Arg::inline_bytes(meta,4),gpu::Arg::buf(linear)},size_t(scan.w)*scan.h,error))return false;
 if(dst!="ProPhoto RGB"&&!isDI&&!o.at("displayOutput").as_bool(false)){
 const Cam16Setup*c=nullptr;if(!cache.cam16(colour,dst,c,error))return false;const auto og=GamutCompressSpec::output_default();double a[9],b[9];c->m_to_xyz.to_row_major(a);c->m_to_rgb.to_row_major(b);auto mx=g->upload_f32(a,9,error),mr=g->upload_f32(b,9,error),table=g->upload_f32(c->c_max_table.data(),c->c_max_table.size(),error);
 const double setup[]={c->F_L,c->N_bb,c->N_cb,c->n,c->z,c->A_w,c->c,c->N_c,c->l_grid.front(),c->l_grid.back(),c->h_grid.front(),c->h_grid[1]-c->h_grid[0],og.knee[0],og.knee[1],og.knee[2],og.lightness_compression[0],og.lightness_compression[1],og.lightness_compression[2],c->white_Jp,c->D_rgb[0],c->D_rgb[1],c->D_rgb[2]};auto conf=g->upload_f32(setup,22,error),compressed=g->alloc(scan.bytes(),error);const uint32_t cm[]={scan.w*scan.h,uint32_t(c->l_grid.size()),uint32_t(c->h_grid.size()),og.lightness_compression_active?1u:0u};if(!mx||!mr||!table||!conf||!compressed)return false;if(!g->dispatch("spk_cam16ucs_compress",{gpu::Arg::buf(linear),gpu::Arg::buf(mx),gpu::Arg::buf(mr),gpu::Arg::buf(table),gpu::Arg::buf(conf),gpu::Arg::inline_bytes(cm,4),gpu::Arg::buf(compressed)},size_t(scan.w)*scan.h,error))return false;linear=std::move(compressed);
 }
 const float v[]={float(get("vignette")/100)};const uint32_t enc[]={scan.w*scan.h,scan.w,scan.h,cctf_mode_for(dst),isDI?1u:0u};auto final=g->alloc(scan.bytes(),error),vp=g->upload(v,sizeof v,error);if(!final||!vp)return false;if(!g->dispatch("spk_web_encode",{gpu::Arg::buf(linear),gpu::Arg::buf(vp),gpu::Arg::inline_bytes(enc,5),gpu::Arg::buf(final)},size_t(scan.w)*scan.h,error))return false;return g->read(final.get(),0,output,scan.bytes(),error);
}
